#nullable enable // autogenerated

using System.Xml;

namespace MVZ2.Metas
{
    public class CurseMetaList
    {
        public CurseMeta[] metas;

        public CurseMetaList(CurseMeta[] metas)
        {
            this.metas = metas;
        }

        public static CurseMetaList FromXmlNode(XmlNode node, string defaultNsp)
        {
            var metas = new CurseMeta[node.ChildNodes.Count];
            for (int i = 0; i < metas.Length; i++)
            {
                var meta = CurseMeta.FromXmlNode(node.ChildNodes[i], defaultNsp, i);
                if (meta != null)
                {
                    metas[i] = meta;
                }
            }
            return new CurseMetaList(metas);
        }
    }
}
